export function computeOffset(box: DOMRectReadOnly, width: number, height: number): FrameOffset {
	const fits = box.width <= width && box.height <= height
	let top = fits ? Math.min(0, height - Math.ceil(box.bottom)) : 0
	let left = fits ? Math.min(0, width - Math.ceil(box.right)) : 0
	const upper = box.top + top
	const start = box.left + left
	if (upper <= 0 && start <= 0 && box.bottom + top > 0 && box.right + left > 0) {
		const rows = fits ? height - box.bottom - top : Number.POSITIVE_INFINITY
		const columns = fits ? width - box.right - left : Number.POSITIVE_INFINITY
		if (rows > -upper) top += Math.min(1 - upper, rows)
		else if (columns > -start) left += Math.min(1 - start, columns)
	}
	return { top, left }
}
